	public static int GetChannel() {
        return GetChannel(GameManager.nowTime.Hour, GameManager.nowTime.Minute, PlayerWork.Week);
    }
	public static int GetChannel(int hour, int minute, global::System.DayOfWeek dayOfWeek) {
        // shipped predicate: the LAST row whose hour AND minute are both <= now (@018cc930)
        int index = Array.FindLastIndex(GameData.DataManager.TvSchedule.TimeTable, data => data.hour <= hour && data.minute <= minute);
        if (index < 0)
            return 0;
        TvSchedule.SheetTimeTable timeTable = GameData.DataManager.TvSchedule.TimeTable[index];
        switch (dayOfWeek)
        {
            case DayOfWeek.Sunday:
                return timeTable.sun;
            case DayOfWeek.Monday:
                return timeTable.mon;
            case DayOfWeek.Tuesday:
                return timeTable.tue;
            case DayOfWeek.Wednesday:
                return timeTable.wed;
            case DayOfWeek.Thursday:
                return timeTable.thu;
            case DayOfWeek.Friday:
                return timeTable.fri;
            case DayOfWeek.Saturday:
                return timeTable.sat;
        }
        return 0;
    }
	public static global::DPData.TV_PROGRAM FindEnableProgram() {
        int channel = GetChannel();
        TvDataTable.Sheetdata[] programs = Array.FindAll(GameData.DataManager.TvDataTable.data,
            data => data.Channel == channel && CheckEnableProgram((TV_PROGRAM)data.TpicID) && FlagCheck(data.BroadCastOpenFlag));
        if (programs.Length == 0)
            return TV_PROGRAM.MAX;
        return (TV_PROGRAM)programs[UnityEngine.Random.Range(0, programs.Length)].TpicID;
    }
	public static bool CheckEnableProgram(global::DPData.TV_PROGRAM id) {
        // both reads happen before the test (two get_tvData calls @018c7f78 / @018c7fd8) -> locals
        int branchData = GetTvBranchData(id);
        bool topicCreate = GetTVTpicCreate(id);
        if (branchData > 0 && topicCreate)
        {
            GetLinkRecord(id, out TV_DATA_ID_INT[] recordInt, out TV_DATA_ID_STR[] recordStr);
            if (recordStr != null && recordStr.Length != 0)
            {
                for (int i = 0; i < recordStr.Length; i++)
                {
                    if (string.IsNullOrWhiteSpace(GetRecordTvStrData(recordStr[i])))
                        return false;
                }
            }
            return true;
        }
        return false;
    }
	public static int[] GetCommercialIndexArray() {
        int[] indexArray = Array.FindAll(GameData.DataManager.TvDataTable.data, data => data.Channel == 0 && FlagCheck(data.BroadCastOpenFlag))
            .Select(data => data.TpicID).ToArray();
        int count = indexArray.Length;
        for (int i = 0; i < count; i++)
        {
            int r = UnityEngine.Random.Range(i, count);
            int tmp = indexArray[i];
            indexArray[i] = indexArray[r];
            indexArray[r] = tmp;
        }
        return indexArray;
    }
	private static bool FlagCheck(global::Dpr.EvScript.EvWork.SYSFLAG_INDEX flagIndex) {
        // 1000 (= SYSFLAG_SAVE_SIZE) is the table's "no open flag" value (@018c9464)
        if (flagIndex == (EvWork.SYSFLAG_INDEX)1000)
            return true;
        return EvDataManager.Instanse.GetSysFlag(flagIndex) != 0;
    }
