	public static void MakeDailyTopic() {
        // Group introduction (loop over MYUSE..DATA9 unrolled in the binary @018cbcd4)
        System.Collections.Generic.List<RANDOMGROUP> groupList = new System.Collections.Generic.List<RANDOMGROUP>();
        for (RANDOMGROUP group = RANDOMGROUP.RANDOMGROUP_MYUSE; group < RANDOMGROUP.RANDOMGROUP_MAX; group++)
        {
            if (RandomGroupWork.ExistCheck(group))
                groupList.Add(group);
        }
        if (groupList.Count > 0)
        {
            RANDOMGROUP group = groupList[UnityEngine.Random.Range(0, groupList.Count)];
            string groupName = RandomGroupWork.GetNamePtr(group, RANDOMGROUP_NAME.RANDOMGROUP_NAME_GROUP);
            string memberName = RandomGroupWork.GetNamePtr(group, RANDOMGROUP_NAME.RANDOMGROUP_NAME_LEADER);
            GroupSyoukai(UnityEngine.Random.Range(0, 18), groupName, memberName);
        }

        // Weather report (switch = jump table @03d49167; case SUNNY draws 1..4, the others fixed, FOG / VOLCANO / SANDSTORM / SPIRIT skip)
        ZoneID zoneID = WeatherReportZone[UnityEngine.Random.Range(0, WeatherReportZone.Length)];
        MapInfo.SheetZoneData zoneData = GameManager.mapInfo[(int)zoneID];
        SYS_WEATHER weather = CalendarEnc.CalEnc_GetWeather(zoneData.ZoneID, zoneData.Weather, SystemTimeWork.IsPenalty());
        int weatherNo = 0;
        switch (weather)
        {
            case SYS_WEATHER.SUNNY:
                weatherNo = UnityEngine.Random.Range(1, 5);
                break;
            case SYS_WEATHER.CLOUDINESS:
                weatherNo = 5;
                break;
            case SYS_WEATHER.RAIN:
                weatherNo = 6;
                break;
            case SYS_WEATHER.STRAIN:
                weatherNo = 7;
                break;
            case SYS_WEATHER.SPARK:
                weatherNo = 11;
                break;
            case SYS_WEATHER.SNOW:
                weatherNo = 8;
                break;
            case SYS_WEATHER.SNOWSTORM:
                weatherNo = 9;
                break;
            case SYS_WEATHER.SNOWSTORM_H:
                weatherNo = 10;
                break;
            case SYS_WEATHER.DIAMONDDUST:
                weatherNo = 12;
                break;
        }
        if (weatherNo > 0)
            WeatherReport(weatherNo, (int)zoneID);

        MakeTairyouhasseiTopic();

        // Type compatibility (AboutAffinityID -> branch: value table @03d0d6f0 = {4, 2, 1, 3}, default 2)
        PokeType type1 = (PokeType)UnityEngine.Random.Range(0, 18);
        PokeType type2 = (PokeType)UnityEngine.Random.Range(0, 18);
        int aisyou;
        switch (Pml.Battle.TypeAffinity.TCalcAffinityAbout(type1, type2, false))
        {
            case Pml.Battle.TypeAffinity.AboutAffinityID.NONE:
                aisyou = 4;
                break;
            case Pml.Battle.TypeAffinity.AboutAffinityID.NORMAL:
                aisyou = 2;
                break;
            case Pml.Battle.TypeAffinity.AboutAffinityID.ADVANTAGE:
                aisyou = 1;
                break;
            case Pml.Battle.TypeAffinity.AboutAffinityID.DISADVANTAGE:
                aisyou = 3;
                break;
            default:
                aisyou = 2;
                break;
        }
        PokemonAisyou(aisyou, (int)type1, (int)type2);

        // Berry information (GrowPhase -> state: value table @03d49258 = {5, 5, 4, 3, 2, 1}, Invalid skips)
        System.Collections.Generic.List<int> placeList = new System.Collections.Generic.List<int>();
        int placeCount = KinomiWork.GetPlaceDataCount();
        for (int i = 0; i < placeCount; i++)
        {
            int placeIndex = KinomiWork.GrowIndexToPlaceIndex(i);
            KinomiPlaceData.SheetSheet1 placeData = KinomiWork.GetPlaceData(placeIndex);
            if (placeData.SeedStartFlag < EvWork.SYSFLAG_INDEX.SYSFLAG_END && FlagWork.GetSysFlag(placeData.SeedStartFlag))
                placeList.Add(placeIndex);
        }
        if (placeList.Count > 0)
        {
            int placeIndex = placeList[UnityEngine.Random.Range(0, placeList.Count)];
            int state;
            switch (KinomiWork.CalcGrowPhase(KinomiWork.GetGrow(placeIndex)))
            {
                case KinomiWork.GrowPhase.Empty:
                    state = 5;
                    break;
                case KinomiWork.GrowPhase.Seed:
                    state = 5;
                    break;
                case KinomiWork.GrowPhase.Sprout:
                    state = 4;
                    break;
                case KinomiWork.GrowPhase.Trunk:
                    state = 3;
                    break;
                case KinomiWork.GrowPhase.Flower:
                    state = 2;
                    break;
                case KinomiWork.GrowPhase.Fruit:
                    state = 1;
                    break;
                default:
                    state = -1;
                    break;
            }
            if (state >= 0)
            {
                KinomiPlaceData.SheetSheet1 placeData = KinomiWork.GetPlaceData(placeIndex);
                if (placeData != null)
                    KinomiJouhou(state, (int)placeData.ZoneID);
            }
        }

        // Wild Pokémon holding an item (MonsNo 1..494, regional dex only, not in IgnoreDouguMotteruYasei, item2 set)
        System.Collections.Generic.List<int> monsList = new System.Collections.Generic.List<int>();
        for (int monsNo = 1; monsNo < (int)MonsNo.MAX; monsNo++)
        {
            PersonalTable.SheetPersonal personal = Pml.Personal.PersonalSystem.GetPersonalData((MonsNo)monsNo, 0);
            if (personal.chihou_zukan_no != 0 && !IgnoreDouguMotteruYasei.Contains(personal.chihou_zukan_no) && personal.item2 != 0)
                monsList.Add(monsNo);
        }
        if (monsList.Count > 0)
        {
            int monsNo = monsList[UnityEngine.Random.Range(0, monsList.Count)];
            DouguMotteruYasei((MonsNo)monsNo, (ItemNo)Pml.Personal.PersonalSystem.GetPersonalData((MonsNo)monsNo, 0).item2);
        }
    }
	public static void MakeTairyouhasseiTopic() {
        if (!EncountDataWork.IsTairyouHassei())
            return;
        ZoneID zoneID = ZoneWork.TairyouHassei_ZoneID();
        MonsLv[] tairyo = GameManager.GetFieldEncountData(zoneID).tairyo;
        if (tairyo == null || tairyo.Length == 0)
            return;
        int start = UnityEngine.Random.Range(0, tairyo.Length);
        for (int i = 0; i < tairyo.Length; i++)
        {
            MonsNo monsNo = tairyo[(start + i) % tairyo.Length].monsNo;
            if (monsNo != MonsNo.NULL)
            {
                TairyouHassei((int)zoneID, monsNo);
                return;
            }
        }
    }
